                command.loanedAt() != null ? command.loanedAt() : LocalDate.now(), reservations);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        saveReservationPort.saveReservationQueue(reservations);
        return loan;
    }
