package com.example.lending.domain;

import java.time.LocalDate;
import java.util.Objects;
import java.util.UUID;

public class Book {

    private final UUID id;
    private final String title;
    private BookStatus status;

    private Book(UUID id, String title, BookStatus status) {
        this.id = Objects.requireNonNull(id, "id");
        if (title == null || title.isBlank()) {
            throw new IllegalArgumentException("title must not be blank");
        }
        this.title = title;
        this.status = Objects.requireNonNull(status, "status");
    }

    public static Book register(String title) {
        return new Book(UUID.randomUUID(), title, BookStatus.AVAILABLE);
    }

    public static Book reconstitute(UUID id, String title, BookStatus status) {
        return new Book(id, title, status);
    }

    // 예약이 걸려 있으면 맨 앞 예약자만 빌릴 수 있고, 빌리는 순간 그 예약은 소진된다.
    public Loan loanTo(Member member, int activeLoanCount, LocalDate today, ReservationQueue reservations) {
        ensureSameBook(reservations);
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.ON_LOAN) {
            throw new BookAlreadyOnLoanException(id);
        }
        reservations.ensureMayBorrow(member.getId());
        member.ensureCanBorrow(activeLoanCount);
        reservations.fulfillFor(member.getId());
        status = BookStatus.ON_LOAN;
        return Loan.start(id, member.getId(), today);
    }

    // 예약은 지금 빌릴 수 없는 책에만 걸 수 있다. 대출 중이거나, 반납됐어도 앞선 예약자를 기다리는 책이다.
    public Reservation reserveFor(Member member, ReservationQueue reservations) {
        ensureSameBook(reservations);
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.AVAILABLE && reservations.isEmpty()) {
            throw new BookAvailableException(id);
        }
        return reservations.enqueue(member.getId());
    }

    private void ensureSameBook(ReservationQueue reservations) {
        if (!id.equals(reservations.getBookId())) {
            throw new IllegalArgumentException("reservations are not for book " + id);
        }
    }

    // 대출(loanTo)과 마찬가지로 반납도 Book 이 Loan 과의 조율을 맡는다.
    // Loan 의 반납 상태는 Loan 이, 책의 대출 상태는 Book 이 각자 바꾼다.
    public void receiveReturn(Loan loan, LocalDate today) {
        if (!id.equals(loan.getBookId())) {
            throw new IllegalArgumentException("loan " + loan.getId() + " is not for book " + id);
        }
        if (loan.isReturned()) {
            throw new LoanAlreadyReturnedException(loan.getId());
        }
        if (status != BookStatus.ON_LOAN) {
            throw new IllegalStateException("book is not on loan: " + id);
        }
        loan.markReturned(today);
        status = BookStatus.AVAILABLE;
    }

    // 훼손·분실된 책을 폐기한다. 대출 중인 책은 반납된 뒤에만 폐기할 수 있다.
    public void discard() {
        if (status == BookStatus.ON_LOAN) {
            throw new BookOnLoanException(id);
        }
        status = BookStatus.DISCARDED;
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public BookStatus getStatus() {
        return status;
    }
}
