import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class WebExceptionHandler {

    @ExceptionHandler(BookAlreadyOnLoanException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleAlreadyOnLoan(BookAlreadyOnLoanException e) {
        return new ErrorResponse("BOOK_ALREADY_ON_LOAN");
    }

    @ExceptionHandler(BookDiscardedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleDiscarded(BookDiscardedException e) {
        return new ErrorResponse("BOOK_DISCARDED");
    }

    @ExceptionHandler(BookOnLoanException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleOnLoan(BookOnLoanException e) {
        return new ErrorResponse("BOOK_ON_LOAN");
    }

    @ExceptionHandler(LoanLimitExceededException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleLoanLimitExceeded(LoanLimitExceededException e) {
        return new ErrorResponse("LOAN_LIMIT_EXCEEDED");
    }

    @ExceptionHandler(MemberAlreadyExistsException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleMemberAlreadyExists(MemberAlreadyExistsException e) {
        return new ErrorResponse("MEMBER_ALREADY_EXISTS");
    }

    @ExceptionHandler(LoanAlreadyReturnedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleAlreadyReturned(LoanAlreadyReturnedException e) {
        return new ErrorResponse("ALREADY_RETURNED");
    }

    @ExceptionHandler(BookAvailableException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleBookAvailable(BookAvailableException e) {
        return new ErrorResponse("BOOK_AVAILABLE");
    }

    @ExceptionHandler(ReservedForOtherException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleReservedForOther(ReservedForOtherException e) {
        return new ErrorResponse("RESERVED_FOR_OTHER");
    }

    @ExceptionHandler(AlreadyReservedException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleAlreadyReserved(AlreadyReservedException e) {
        return new ErrorResponse("ALREADY_RESERVED");
    }

    @ExceptionHandler(BookNotFoundException.class)
    public ProblemDetail handleNotFound(BookNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(MemberNotFoundException.class)
    public ProblemDetail handleMemberNotFound(MemberNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(LoanNotFoundException.class)
    public ProblemDetail handleLoanNotFound(LoanNotFoundException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ProblemDetail handleInvalidInput(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}
