package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    @Test
    void member_loans_are_paged_and_exclude_returned_loans() throws Exception {
        String memberId = registerMember("한지우");
        String first = loanBookOn(registerBook("Clean Code"), memberId, "2026-02-02");
        String second = loanBookOn(registerBook("Refactoring"), memberId, "2026-02-03");
        String returned = loanBookOn(registerBook("반납한 책"), memberId, "2026-02-04");
        String third = loanBookOn(registerBook("Test Driven Development"), memberId, "2026-02-05");
        loanBookOn(registerBook("다른 회원의 책"), registerMember("다른 회원"), "2026-02-01");
        mockMvc.perform(post("/loans/{loanId}/return", returned)).andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "0").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(2))
                .andExpect(jsonPath("$.totalCount").value(3))
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].loanId").value(first))
                .andExpect(jsonPath("$.items[0].bookId").isNotEmpty())
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.items[1].loanId").value(second));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "1").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.page").value(1))
                .andExpect(jsonPath("$.totalCount").value(3))
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].loanId").value(third))
                .andExpect(jsonPath("$.items[0].title").value("Test Driven Development"));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "5").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalCount").value(3))
                .andExpect(jsonPath("$.items.length()").value(0));
    }

    @Test
    void member_without_loans_gets_an_empty_list() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", registerMember("빈손")))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.totalCount").value(0))
                .andExpect(jsonPath("$.items.length()").value(0));
    }

    @Test
    void member_loans_of_unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void member_loans_with_invalid_paging_returns_400() throws Exception {
        String memberId = registerMember("오페이지");
        String[][] params = {{"-1", "2"}, {"0", "0"}, {"0", "101"}};
        for (String[] p : params) {
            mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", p[0]).param("size", p[1]))
                    .andExpect(status().isBadRequest());
        }
    }

    @Test
    void searching_books_by_title_matches_substring_case_insensitively() throws Exception {
        String token = UUID.randomUUID().toString().replace("-", "");
        String springId = registerBook("Spring in Action " + token);
        String bootId = registerBook("Learning SPRING Boot " + token);
        registerBook("Clean Code " + token);

        mockMvc.perform(get("/books").param("title", "spring in action " + token.toUpperCase()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].id").value(springId))
                .andExpect(jsonPath("$[0].title").value("Spring in Action " + token))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"));

        mockMvc.perform(get("/books").param("title", "sPrInG"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[?(@.id == '" + springId + "')]").exists())
                .andExpect(jsonPath("$[?(@.id == '" + bootId + "')]").exists())
                .andExpect(jsonPath("$[?(@.title == 'Clean Code " + token + "')]").doesNotExist());
    }

    @Test
    void searching_books_with_no_match_returns_empty_list() throws Exception {
        mockMvc.perform(get("/books").param("title", "no-such-title-" + UUID.randomUUID()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void searching_books_treats_like_wildcards_literally() throws Exception {
        String token = UUID.randomUUID().toString().replace("-", "");
        registerBook("100% Pure " + token);
        registerBook("100 Pure " + token);

        mockMvc.perform(get("/books").param("title", "100% pure " + token))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].title").value("100% Pure " + token));
    }

    @Test
    void searching_books_without_title_returns_400() throws Exception {
        mockMvc.perform(get("/books")).andExpect(status().isBadRequest());
        mockMvc.perform(get("/books").param("title", " ")).andExpect(status().isBadRequest());
    }

    @Test
    void discarding_an_available_book_marks_it_discarded() throws Exception {
        String bookId = registerBook("훼손된 책");

        mockMvc.perform(post("/books/{id}/discard", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(bookId))
                .andExpect(jsonPath("$.title").value("훼손된 책"))
                .andExpect(jsonPath("$.status").value("DISCARDED"));

