    }

    @Test
    void reservations_queue_in_order_and_front_reserver_gets_priority_after_return() throws Exception {
        String bookId = registerBook("예약 도서");
        String borrower = registerMember("대출자");
        String first = registerMember("첫째");
        String second = registerMember("둘째");
        String stranger = registerMember("외부인");
        String loanId = loanBook(bookId, borrower);

        String firstReservationId = reserve(bookId, first, 1);
        String secondReservationId = reserve(bookId, second, 2);

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].reservationId").value(firstReservationId))
                .andExpect(jsonPath("$[0].memberId").value(first))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].reservationId").value(secondReservationId))
                .andExpect(jsonPath("$[1].memberId").value(second))
                .andExpect(jsonPath("$[1].position").value(2));

        mockMvc.perform(post("/loans/{loanId}/return", loanId)).andExpect(status().isOk());

        for (String other : new String[]{stranger, second, borrower}) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(objectMapper.writeValueAsString(new LoanBody(bookId, other))))
                    .andExpect(status().isConflict())
                    .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));
        }

        String firstLoanId = loanBook(bookId, first);

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].reservationId").value(secondReservationId))
                .andExpect(jsonPath("$[0].position").value(1));

        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId)).andExpect(status().isOk());
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, stranger))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));
        String secondLoanId = loanBook(bookId, second);

        mockMvc.perform(get("/books/{bookId}/reservations", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));

        mockMvc.perform(post("/loans/{loanId}/return", secondLoanId)).andExpect(status().isOk());
        loanBook(bookId, stranger);
    }

