package com.example.lending.adapter.out.credit;

import com.example.lending.application.port.out.CreditCheckPort;
import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Member;
import com.examplecredit.sdk.CreditCheckClient;
import com.examplecredit.sdk.CreditCheckResponse;
import org.springframework.stereotype.Component;

// ExampleCredit SDK 로 신용조회를 하고, 업체 응답 타입을 도메인의 CreditCheck 로 옮겨 담는다.
// 업체 타입(CreditCheckResponse)은 이 어댑터 밖으로 나가지 않는다.
@Component
public class ExampleCreditAdapter implements CreditCheckPort {

    private final CreditCheckClient client;

    public ExampleCreditAdapter(CreditCheckClient client) {
        this.client = client;
    }

    @Override
    public CreditCheck check(Member member) {
        CreditCheckResponse response = client.check(member.getId().toString(), member.getName());
        if (response == null) {
            throw new IllegalStateException("credit check returned no response for member " + member.getId());
        }
        CreditCheckResponse.Provider provider = response.provider;
        return new CreditCheck(response.approved, response.score, response.reasonCodes, response.checkedAt,
                provider != null ? provider.name : null, provider != null ? provider.version : null);
    }
}
=== examplecredit/sdk/CreditCheckClient.java
package com.examplecredit.sdk;

import java.time.Instant;
import java.util.List;

public class CreditCheckClient {
    /** POST https://credit.example.com/v2/check — 현재는 스텁 */
    public CreditCheckResponse check(String memberId, String memberName) {
        CreditCheckResponse r = new CreditCheckResponse();
        r.approved = memberName == null || !memberName.startsWith("BLOCKED");
        r.score = r.approved ? 742 : 410;
        r.reasonCodes = List.of(r.approved ? "OK" : "WATCHLIST");
        r.checkedAt = Instant.now();
        r.provider = new CreditCheckResponse.Provider();
        r.provider.name = "ExampleCredit";
        r.provider.version = "2.3";
        return r;
    }
}
