package com.example.lending.domain;

import java.time.Instant;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

// 대출 직전에 받은 외부 신용조회 결과. 분쟁에 대비해 대출 기록과 함께 그대로 보관한다.
public record CreditCheck(boolean approved, int score, List<String> reasonCodes, Instant checkedAt,
                          String providerName, String providerVersion) {

    public CreditCheck {
        Objects.requireNonNull(checkedAt, "checkedAt");
        reasonCodes = reasonCodes == null ? List.of() : List.copyOf(reasonCodes);
    }

    public void ensureApproved(UUID memberId) {
        if (!approved) {
            throw new CreditRejectedException(memberId, reasonCodes);
        }
    }
}
