package com.example.lending.adapter.in.web;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

import java.time.Instant;
import java.time.LocalDate;
import java.util.UUID;

public record LoanDetailResponse(UUID loanId, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                 CreditCheckResponse creditCheck) {

    static LoanDetailResponse from(Loan loan) {
        return new LoanDetailResponse(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), CreditCheckResponse.from(loan.getCreditCheck()));
    }

    public record CreditCheckResponse(boolean approved, int score, Instant checkedAt) {

        static CreditCheckResponse from(CreditCheck creditCheck) {
            return new CreditCheckResponse(creditCheck.approved(), creditCheck.score(), creditCheck.checkedAt());
        }
    }
}
